from lib import *
M=mcq;F=tf;S=short;N=num
chapter(4,'maths','ticking-clocks-and-turning-calendar','Ticking Clocks and Turning Calendar',
 ('Parv\'s birthday','Parv was born on 29 February 2016. A date like 29 February comes only once in four years! His friends wonder how that can be, and we find out by studying the calendar.'),
 [('Leap years',['Years having the date 29 February are called leap years. A leap year has one extra day and comes every four years.','Look at February 2024 and February 2025: February 2024 has 29 days and February 2025 has 28 days.','Leap years around 2024 are 2016, 2020, 2024, 2028, 2032 and 2036.','Most years have 365 days, so a leap year has 366 days.']),
  ('Days, weeks and months',['We say today, yesterday, tomorrow, day after tomorrow and day before yesterday using the days of the week.','If July 1 is a Monday, the next Mondays are July 8 and July 15, because a week has 7 days.','We write festivals by the month they fall in. For example, you can write the month of your favourite festival.','If July 15 falls on a certain day, August 15 will fall on a different day, because months have different numbers of days. Look at your calendar and find the pattern.']),
  ('Reading dates and finding age',['04/07/2024 is in DD/MM/YYYY format and is read as 4th July 2024.','Laali was born on 04/07/2014 and Chotu on 04/12/2019. Laali is older by 5 years and 5 months.','Laali turns 5 on 04/07/2019 and Chotu\'s 10th birthday is on 04/12/2029.','On a biscuit packet the manufacturing date and the expiry date tell us how old the packet is and how many days it is safe to eat.'])],
 [('Laali was born on 04/07/2014 and Chotu on 04/12/2019. Who is older and by how much?',[('Compare the years first: 2014 comes before 2019, so Laali is older.','The earlier birth date is the older person.'),('From 04/07/2014 to 04/12/2019 is 5 years and 5 months, so Laali is older by 5 years 5 months.','From July to December is 5 months.')]),
  ('July 1 is a Monday. Which dates are the next two Mondays?',[('A week has 7 days, so add 7 to the date.','Same day comes every 7 days.'),('1 + 7 = 8 and 8 + 7 = 15, so July 8 and July 15.','Mondays are one week apart.')])],
 ('Explain what a leap year is and how to read a date like 04/07/2024.',['29 February, every four years, 366 days','DD/MM/YYYY','Weeks have 7 days'],['A leap year has 364 days']),
 ['A leap year has 366 days and a 29 February.','04/07/2024 is read as 4 July 2024.','The same day of the week repeats every 7 days.'],
 [N('1',1,'How many days does a leap year have?',366,'365 + 1 extra day (29 February) = 366.',[(365,'That is a normal year')],'days'),
  M('2',1,'Which is a leap year?','2024',[('2025','February 2025 has only 28 days'),('2022','Leap years come every four years from 2020')],'2024 has a 29 February.'),
  F('3',1,'The date 04/07/2024 means 4th July 2024.',True,'DD/MM/YYYY means day, month, year.'),
  M('4',2,'July 1 is Monday. What is the date of the next Monday?','July 8',[('July 2','That is Tuesday'),('July 7','That is Sunday')],'One week later is 1 + 7 = 8.'),
  N('5',2,'How many days are there in February 2024?',29,'2024 is a leap year, so February has 29 days.',[(28,'That is for a normal year')],'days'),
  S('6',2,'Which is the next leap year after 2024?',['2028'],'Leap years come every four years: 2024, 2028.'),
  M('7',3,'Laali (born 04/07/2014) and Chotu (born 04/12/2019): who is older?','Laali',[('Chotu','He was born later'),('Same age','Their birth dates differ')],'Laali was born earlier, so she is older by 5 years 5 months.'),
  F('8',3,'A normal year has 365 days.',True,'A leap year has one extra day, making 366.')])
chapter(4,'maths','the-transport-museum','The Transport Museum',
 ('Mystery matrix','At the transport museum, the children play a number puzzle called Mystery Matrix. Boxes show products, and you fill in the missing numbers that multiply to give them. Along the way they discover how to multiply by 10 and how to build the times-15 table.'),
 [('Multiplying by 10',['2 x 10 is 2 tens, which is 20. 5 x 10 is 5 tens, which is 50. 8 x 10 is 8 tens, which is 80.','10 x 10 is 10 tens, which is 1 hundred, written 100.','So to multiply a number by 10 we count that many tens.']),
  ('Splitting an arrangement',['A 5 x 15 arrangement has 5 rows of 15 pebbles. We split each row into 10 and 5.','5 x 15 = 5 x 10 plus 5 x 5 = 50 + 25 = 75.','We can do the same for 1 x 15, 2 x 15 and so on, to build the times-15 table.']),
  ('The times-15 table',['1 x 15 = 15, 2 x 15 = 30, 3 x 15 = 45, 4 x 15 = 60, 5 x 15 = 75, 6 x 15 = 90, 7 x 15 = 105, 8 x 15 = 120, 9 x 15 = 135, 10 x 15 = 150.','Compare it with the times-5 table: 5, 10, 15, 20, 25, 30, 35, 40, 45, 50. Each answer in the times-15 table is 10 times the numbers in the times-5 table of the same row number minus what is left, or simply 3 times the times-5 answer, because 15 is 3 x 5.','Subtracting a times-5 answer from the times-15 answer gives a times-10 answer: 15 - 5 = 10, 30 - 10 = 20, 45 - 15 = 30.','Try to build the times-11 to times-20 tables the same way and compare each with the smaller table, like times-1 with times-11 and times-2 with times-12.'])],
 [('Find 5 x 15 by splitting.',[('Split 15 into 10 and 5.','Easier numbers to multiply.'),('5 x 10 = 50 and 5 x 5 = 25, then 50 + 25 = 75.','Add the two products.')]),
  ('Find 7 x 15 using 7 x 10 and 7 x 5.',[('7 x 10 = 70.','Times-10 first.'),('7 x 5 = 35, so 70 + 35 = 105.','Add the parts.')])],
 ('Explain how splitting 15 into 10 and 5 helps in multiplying by 15.',['Multiply by 10 and by 5 separately','Add the two answers','Times-15 = times-10 + times-5'],['Times-15 is the same as times-5']),
 ['Multiplying by 10 gives that many tens.','Splitting 15 into 10 and 5 builds the times-15 table.','Times-15 = times-10 + times-5.'],
 [N('1',1,'What is 8 x 10?',80,'8 tens make 80.',[(18,'You added')]),
  N('2',1,'What is 5 x 15?',75,'5 x 10 + 5 x 5 = 50 + 25 = 75.',[(20,'You added instead of multiplying')]),
  F('3',1,'10 tens make 1 hundred.',True,'10 x 10 = 100.'),
  N('4',2,'What is 4 x 15?',60,'4 x 10 + 4 x 5 = 40 + 20 = 60.',[(19,'That is 4 + 15')]),
  M('5',2,'Which two numbers add to make 15 for easy multiplying?','10 and 5',[('7 and 7','That makes 14'),('9 and 9','That makes 18')],'15 = 10 + 5, and both are easy to multiply.'),
  N('6',2,'What is 10 x 15?',150,'10 tens of 15 is 150, or 10 x 10 + 10 x 5 = 100 + 50.',[(25,'You added')]),
  S('7',3,'What is 7 x 15?',['105'],'7 x 10 = 70 and 7 x 5 = 35, so 105.'),
  F('8',3,'The times-15 table is the times-10 table plus the times-5 table.',True,'15 = 10 + 5, so each answer is the sum of the two table answers.')])
